  const cube = boxMesh([1, 1, 1], unlit("#6b5cff"));
  cube.name = "Cube";
  const marker = sphereMesh(0.15, unlit("#ef4444"));
  marker.name = "Marker";
  marker.position.set(0, 0, 0.75);
  cube.add(marker);
  scene.add(cube);

